import java.util.concurrent.CopyOnWriteArrayList;

interface TickerObserver {
    void onPrice(StockTicker ticker); // pull model: observer reads what it needs
}

class StockTicker {
    private final CopyOnWriteArrayList<TickerObserver> observers = new CopyOnWriteArrayList<>();
    private volatile double price;

    public AutoCloseable attach(TickerObserver o) {
        observers.add(o);
        return () -> detach(o); // caller must close; makes leak explicit
    }

    public void detach(TickerObserver o) {
        observers.remove(o);
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double next) {
        if (Double.compare(price, next) == 0) return; // coalesce: no change, no storm
        this.price = next; // 1. commit first
        notifyObservers(); // 2. notify after commit
    }

    private void notifyObservers() {
        // CopyOnWriteArrayList iterates over a snapshot: detach inside update is safe.
        for (TickerObserver o : observers) {
            try {
                o.onPrice(this);
            } catch (RuntimeException ex) {
                // 3. isolate failures: one bad observer must not starve the rest
                System.err.println("observer failed: " + ex);
            }
        }
    }
}
